csv_path = OUT / "waterway_crossing_contact_register.csv"
headers = ["route_segment", "feature_id", "station_from_feature_start", "candidate_waterway", "screening_confidence", "gis_evidence", "likely_permit_authorities", "verified_contact_channels", "records_and_questions_to_request", "priority_and_schedule_gate"]
with csv_path.open("w", newline="", encoding="utf-8-sig") as f:
    w = csv.writer(f)
    w.writerow(headers)
    w.writerows(rows)

doc = Document()
sec = doc.sections[0]
sec.orientation = WD_ORIENT.PORTRAIT
sec.page_width, sec.page_height = Inches(8.5), Inches(11)
sec.top_margin = Inches(.62); sec.bottom_margin = Inches(.62); sec.left_margin = Inches(.72); sec.right_margin = Inches(.72)
styles = doc.styles
styles['Normal'].font.name = 'Aptos'; styles['Normal'].font.size = Pt(9.3); styles['Normal'].font.color.rgb = RGBColor(40, 49, 58)
styles['Normal'].paragraph_format.space_after = Pt(4)
for nm, size, color in [('Title', 25, '17324D'), ('Heading 1', 16, '17324D'), ('Heading 2', 12, '176B73'), ('Heading 3', 10, '176B73')]:
    st = styles[nm]; st.font.name = 'Aptos Display'; st.font.size = Pt(size); st.font.bold = True; st.font.color.rgb = RGBColor.from_string(color)

def shade(cell, fill):
    tcPr = cell._tc.get_or_add_tcPr(); shd = OxmlElement('w:shd'); shd.set(qn('w:fill'), fill); tcPr.append(shd)

def set_cell_text(cell, text, bold=False, color=None, size=8.5):
    cell.text = ''
    p = cell.paragraphs[0]; p.paragraph_format.space_after = Pt(0)
    r = p.add_run(text); r.bold = bold; r.font.name = 'Aptos'; r.font.size = Pt(size)
    if color: r.font.color.rgb = RGBColor.from_string(color)
    cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER

def add_bullet(text):
    p = doc.add_paragraph(style='List Bullet'); p.paragraph_format.left_indent = Inches(.22); p.paragraph_format.first_line_indent = Inches(-.12); p.paragraph_format.space_after = Pt(2); p.add_run(text)

p = doc.add_paragraph(style='Title'); p.add_run('Waterway Crossing Permits and Agency Contact Plan')
p = doc.add_paragraph(); p.paragraph_format.space_after = Pt(9)
r = p.add_run('Route screening across Segment 0, Segment 1, and Chicago Spurs'); r.bold = True; r.font.size = Pt(11); r.font.color.rgb = RGBColor(23,107,115)

doc.add_heading('Decision for the engineering team', 1)
doc.add_paragraph('The route inventory contains 16 mapped or candidate waterway features: eight in Segment 0, six in Segment 1, and two in Chicago Spurs. They are not 16 confirmed permit crossings. Several are unnamed drainage leads, and one Segment 0 feature has no mapped channel intersection. Before pricing or fixing a construction method, resolve those locations in the field and with bridge, culvert, ROW, and floodway records.')
doc.add_paragraph('Run the jurisdiction work in parallel: (1) one station-indexed Corps pre-application and jurisdictional review, (2) state water-quality and floodway applicability questions, and (3) road/bridge/landowner records requests for each crossing. Base design should compare HDD below the surveyed bed and scour envelope with any separately owner-approved bridge corridor. A bridge/structure record is not attachment permission.')

doc.add_heading('Permit gates that control the route', 1)
for t in [
 'Federal Section 10 and Section 404 are different triggers. A telecommunications line over a listed Section 10 water can require Section 10 authorization under 2026 NWP 57 even with no dredge/fill. NWP 57 requires a PCN when Section 10 authorization is required. HDD beneath a nonnavigable channel with no discharge may have a different federal path; pits, mats, access fill, bank work, or drilling-fluid release can change it.',
 'For Ohio waters, ask USACE Huntington feature-by-feature whether Section 10/404 applies. The Scioto and Olentangy are on the Ohio Section 10 list. Do not extend that conclusion to every mapped tributary. Ohio EPA 401 or isolated-wetland review depends on the actual federal/discharge and state-wetland facts.',
 'At Home Road over O’Shaughnessy Reservoir, the bridge/road process is County-led with separate City Water land review where City property is occupied. The new Columbus water intake makes the NWP 57 public-intake condition a written Corps decision gate.',
 'For Chicago Spurs, IDNR OWR may regulate public waters/floodway; Illinois EPA 2026 Section 401 conditions can require individual certification at project-wide disturbance thresholds. The route-feature chain lengths exceed 1.5 miles for both identified spurs, but IEPA must confirm what work and project boundary count.',
 'Floodplain permitting is usually administered by the local NFIP community. ODNR and IDNR provide state-level roles, but they do not replace the local floodplain administrator, road controller, or landowner.'
]: add_bullet(t)

doc.add_heading('Who to contact first', 1)
contacts = [
 ('USACE Huntington District (Ohio)', 'Submit through the Regulatory Request System (RRS) for a project-level pre-application/JD request; general permit mailbox LRH.permits@usace.army.mil. Ohio program contact page lists Huntington at 304-399-5210. Ask for a crossing-by-crossing Section 10/404 determination, NWP 57 eligibility, PCN trigger, and whether to request preliminary or approved jurisdictional determinations.'),
 ('USACE Chicago District', 'RRS for pre-application/JD. New permit applications: ChicagoRequests@usace.army.mil; general regulatory inquiries: LRCREGWEB@usace.army.mil; 312-846-5530. Ask Section 10/404, 2026 Illinois regional PCN conditions, Hine’s emerald dragonfly screening, and NWP 57 coverage.'),
 ('Ohio EPA 401 and Isolated Wetlands', 'Start with eBusiness Center pre-application. Rachel Secrest, supervisor, 740-380-5433; James Morris, coordinator, james.morris@epa.ohio.gov, 614-644-2146. Ask whether a proposed method creates a 401 or isolated-wetland permit trigger and which 2026 Ohio NWP certification applies.'),
 ('Illinois EPA 401', 'Prefiling/certification questions: epa.401.bow@illinois.gov. Darren Gove, darren.gove@illinois.gov, 217-782-3362. Ask in writing how the NWP 57 project boundary, linear disturbance length, staging/HDD work, Salt Creek sidecast, and any public-water-intake condition affect the 2026 certification.'),
 ('IDNR Office of Water Resources, NE Illinois', 'Bill Boyd, P.E., William.Boyd@Illinois.gov, 847-608-3116; general permit/applicability mailbox dnr.dwrm@illinois.gov. Send a sufficient map and concept for a no-cost applicability review; ask public-water and Part 3708 floodway status, and Statewide Permit 8 / Regional Permit 3 eligibility.'),
 ('Delaware County Engineer and Columbus Water', 'County utility/ROW intake: dceopermits@co.delaware.oh.us. Columbus Watershed: watershed@columbus.gov, 614-645-1721. Home Road Water Plant project contact Mark Eppich: MMEppich@columbus.gov. Ask for bridge-specific attachment procedure, bridge plans/inspection and utility inventory, City property rights pathway, intake restrictions and construction coordination.'),
 ('Union and Licking County road records', 'Union County Engineer: engineer@unioncountyohio.gov, 937-645-3021. Licking County utility/ROW contact Tyler Dye: tdye@lcounty.com, 740-670-5285. Request controller/ROW/ditch/bridge ownership, plans, as-builts, inspections, and permit records for the exact station/coordinates.'),
 ('Franklin County roads and floodplain', 'County Engineer records: fracoeng@franklincountyengineer.org, 614-525-3030. Unincorporated County floodplain: planning@franklincountyohio.gov. Ask who controls road/bridge/ditch at each location; city or township authority may supersede County floodplain administration.'),
 ('Cook County DoTH / Elk Grove Village', 'Cook County highway permits: hwy.permits@cookcountyil.gov, 312-603-1670. Elk Grove Engineering: Engineering@elkgrove.org, 847-357-4220. Confirm highway ROW, drainage/culvert owner, local floodplain authority and filing requirements. Cook County recommends utility permits 2–3 months before work.'),
 ('ODOT District 6 and Ohio Scenic Rivers', 'ODOT state ROW/utility questions: Wendi Snyder, Wendi.Snyder@dot.ohio.gov, 614-728-8062; use only if work enters ODOT ROW or a state structure. Olentangy Scenic River contact: Heather Doherty, Heather.Doherty@dnr.ohio.gov, 740-258-0567; ask if ORC 1517.15 review applies to the project sponsor/funding and municipal-limit context.'),
]
tbl = doc.add_table(rows=1, cols=2); tbl.alignment = WD_TABLE_ALIGNMENT.CENTER; tbl.style = 'Table Grid'
for c, txt in zip(tbl.rows[0].cells, ['Office', 'Email / submission path and exact ask']): set_cell_text(c, txt, True, 'FFFFFF', 9); shade(c, '17324D')
for name, contact in contacts:
    c = tbl.add_row().cells; set_cell_text(c[0], name, True, size=8.1); set_cell_text(c[1], contact, size=8.1)

doc.add_heading('What every pre-application package should contain', 1)
for t in [
 'A georeferenced overview plus one detail sheet per feature: route station from the supplied KMZ feature start, latitude/longitude, county/township/municipality, water/wetland IDs, and nearby bridge/culvert SFN where available.',
 'Surveyed channel bed, banks/OHWM, wetlands, culvert/bridge limits, existing utilities, legal ROW/property boundaries, mapped floodway and construction access. Label GIS candidates as unverified until field checked.',
 'Plan/profile for each method under consideration: HDD bore path and cover below bed/scour, entry/exit pits, temporary mats/platforms, access/laydown, bridge attachment details/clearances if applicable, and permanent/temporary impact table in acres and linear feet.',
 'Construction sequence, erosion/sediment controls, frac-out monitoring/containment/stop-work and notification procedure, water-quality protection, restoration, inspection and emergency repair plan.',
 'A separate written question for each agency: jurisdiction/classification, permit/authorization type, preapplication or application channel, required studies/plans, filing fees, review clock after completeness, and what written determination is needed before final design.'
]: add_bullet(t)

doc.add_heading('Crossing-by-crossing register', 1)
doc.add_paragraph('Stations below are measured from each source KMZ feature start, not a project-wide route milepost. GIS confidence describes map evidence only; it is not a jurisdictional determination or title opinion.')

segments = ['Segment 0', 'Segment 1', 'Chicago Spurs']
for seg in segments:
    doc.add_heading(seg, 2)
    for r in rows:
        if r[0] != seg: continue
        p = doc.add_paragraph(); p.paragraph_format.space_before = Pt(5); p.paragraph_format.space_after = Pt(1)
        p.paragraph_format.keep_with_next = True
        rr = p.add_run(f'{r[1]}  |  {r[3]}  |  station {r[2]}'); rr.bold = True; rr.font.color.rgb = RGBColor(23,107,115); rr.font.size = Pt(10)
        items = [('Screen', r[4]), ('Evidence', r[5]), ('Permit route', r[6]), ('Who to email', r[7]), ('Next action', r[8]), ('Gate', r[9])]
        for idx, (label, val) in enumerate(items):
            p = doc.add_paragraph(); p.paragraph_format.left_indent = Inches(.13); p.paragraph_format.space_after = Pt(2)
            p.paragraph_format.keep_together = True
            p.paragraph_format.keep_with_next = idx < len(items) - 1
            x = p.add_run(label + ': '); x.bold = True; p.add_run(val)

